556: ) -> PlotContent {
557:     let (mut paper_wires, mut model_wires) = scene.plot_wire_groups(render_mode_override);
558:     // A viewport border plots whenever its layer plots, as in the reference
559:     // application: the page setup's plot-viewport-borders flag (off in its
560:     // layouts) does not hide it.
