41: 
42:             // ── Fast path: return cached projected wires ──────────────────
43:             if !plot {
44:                 let cache = self.paper_projected_cache.borrow();
45:                 if let Some((cached_epoch, ref wires)) = cache.get(&vp_handle) {
46:                     if *cached_epoch == self.geometry_epoch {
47:                         result.extend_from_slice(wires);
48:                         continue;
49:                     }
50:                 }
51:             }
52: 
53:             // ── Cache miss: compute projection ────────────────────────────
54: 
55:             // Use camera_for_viewport so the axes match the GPU renderer exactly.
56:             let cam_frame = match self.camera_for_viewport(vp_handle) {
57:                 Some(c) => c,
58:                 None => continue,
59:             };
60:             let view_right = cam_frame.rotation * glam::Vec3::X;
61:             let view_up = cam_frame.rotation * glam::Vec3::Y;
62: 
63:             // Scale (paper units per model unit) comes straight from the camera
64:             // the GPU uses: the model height shown is `2 * ortho_size`, mapped
65:             // onto `vp.height` of paper. `camera_for_viewport` already made the
66:             // saved-view-vs-auto-fit decision (with the twist-correct overlap
67:             // test), so deriving scale from it keeps the CPU projection (used
68:             // for hit-test / snap / fit) locked to the GPU render — no second,
69:             // independently-computed scale that could disagree under a twist.
70:             let view_height_eff = (cam_frame.ortho_size() * 2.0) as f64;

