#!/usr/bin/env python3
"""
Master Floor Plan Construction Script
Executes all drafting, block definitions, annotations, presentation layouts,
and publication for floor plan exercise.dwg and example 2.pdf.
"""
import subprocess, json, math, sys, os, time

class OCS:
    def __init__(self):
        self.proc = subprocess.Popen(
            ['/usr/local/bin/OpenCADStudio', '--mcp'],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        self.req_id = 1
        self._init()
        self.sid = self.get_session_id()

    def _call_raw(self, method, params):
        req = {'jsonrpc': '2.0', 'id': self.req_id, 'method': method, 'params': params}
        self.req_id += 1
        self.proc.stdin.write(json.dumps(req) + '\n')
        self.proc.stdin.flush()
        line = self.proc.stdout.readline()
        return json.loads(line)

    def _init(self):
        self._call_raw('initialize', {
            'protocolVersion': '2024-11-05',
            'capabilities': {},
            'clientInfo': {'name': 'drafter', 'version': '1.0'}
        })

    def tool(self, name, args):
        res = self._call_raw('tools/call', {'name': name, 'arguments': args})
        if res.get('error'):
            raise RuntimeError(f"Tool {name} error: {res['error']}")
        return res['result']

    def get_session_id(self):
        res = self.tool('ocs_sessions', {})
        sc = res.get('structuredContent', {})
        sess_list = sc.get('result', [])
        if not sess_list:
            text = res['content'][0]['text']
            sess_list = json.loads(text)
        return sess_list[0]['session_id']

    def run(self, cmd):
        return self.tool('ocs_run', {'cmd': cmd})

    def cancel(self):
        return self.tool('ocs_cancel', {})

    def select(self, handles=None, clear=True):
        args = {'clear': clear}
        if handles is not None:
            args['handles'] = handles
        return self.tool('ocs_select', args)

    def execute(self, op, **kwargs):
        req = {'op': op, 'request_id': f'req_{self.req_id}', **kwargs}
        return self.tool('ocs_execute', {'ocs_session_id': self.sid, 'request': req})

    def read_records(self, collection, handles=None):
        params = {'collection': collection}
        if handles is not None:
            params['handles'] = handles
        return self.tool('ocs_read', {'ocs_session_id': self.sid, 'op': 'records', 'parameters': params})

    def query(self, **kwargs):
        return self.tool('ocs_query', kwargs)

    def create_entities(self, entities):
        chunk_size = 50
        created = []
        for i in range(0, len(entities), chunk_size):
            chunk = entities[i:i+chunk_size]
            res = self.execute('entities_create', entities=chunk)
            sc = res.get('structuredContent', {})
            handles = sc.get('result', {}).get('handles', [])
            created.extend(handles)
        return created

    def close(self):
        self.proc.kill()

print("Master drafting helper ready.")

